CREATE TABLE credbound_instance (singleton boolean PRIMARY KEY, initialized_at timestamptz NOT NULL);
CREATE TABLE credbound_users (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), display_name text NOT NULL, disabled boolean NOT NULL, last_seen_at timestamptz, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE credbound_user_emails (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), user_id uuid NOT NULL REFERENCES credbound_users(id), address text NOT NULL UNIQUE, is_primary boolean NOT NULL, verified_at timestamptz, verification_digest bytea, verification_expires_at timestamptz, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE credbound_password_credentials (user_id uuid PRIMARY KEY REFERENCES credbound_users(id), hash text NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE credbound_workspaces (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), name text NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, disabled_at timestamptz);
CREATE TABLE credbound_memberships (workspace_id uuid NOT NULL REFERENCES credbound_workspaces(id), user_id uuid NOT NULL REFERENCES credbound_users(id), role text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended')), provisioning_source text NOT NULL DEFAULT 'local', created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, PRIMARY KEY (workspace_id, user_id));
CREATE TABLE credbound_instance_administrators (user_id uuid PRIMARY KEY REFERENCES credbound_users(id), role text NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE credbound_sso_identities (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), user_id uuid NOT NULL REFERENCES credbound_users(id), provider_configuration_id uuid NOT NULL CHECK (substring(provider_configuration_id::text from 15 for 1) = '7' AND substring(provider_configuration_id::text from 20 for 1) IN ('8', '9', 'a', 'b')), provider_kind text NOT NULL, issuer text NOT NULL, subject text NOT NULL, email text NOT NULL, created_at timestamptz NOT NULL, last_used_at timestamptz, UNIQUE (provider_configuration_id, issuer, subject));
CREATE TABLE credbound_totp_factors (user_id uuid PRIMARY KEY REFERENCES credbound_users(id), encrypted_secret bytea NOT NULL, active boolean NOT NULL, last_used_step bigint NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE credbound_recovery_codes (user_id uuid NOT NULL REFERENCES credbound_users(id), digest bytea NOT NULL, used_at timestamptz, PRIMARY KEY (user_id, digest));
CREATE TABLE credbound_passkeys (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), user_id uuid NOT NULL REFERENCES credbound_users(id), name text NOT NULL, credential_id bytea NOT NULL UNIQUE, credential_json bytea NOT NULL, created_at timestamptz NOT NULL, last_used_at timestamptz);
CREATE TABLE credbound_personal_access_tokens (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), user_id uuid NOT NULL REFERENCES credbound_users(id), name text NOT NULL, prefix text NOT NULL UNIQUE, digest bytea NOT NULL, workspace_id uuid REFERENCES credbound_workspaces(id), scopes_json jsonb NOT NULL, created_at timestamptz NOT NULL, expires_at timestamptz, last_used_at timestamptz, revoked_at timestamptz);
CREATE TABLE credbound_audit_events (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), occurred_at timestamptz NOT NULL, actor_kind text NOT NULL DEFAULT 'user' CHECK (actor_kind IN ('user', 'service', 'system')), actor_id uuid, action text NOT NULL, resource_type text NOT NULL, resource_id text NOT NULL, workspace_id uuid, outcome text NOT NULL, reason text NOT NULL);
CREATE TABLE credbound_scim_configurations (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), workspace_id uuid NOT NULL REFERENCES credbound_workspaces(id), enabled boolean NOT NULL, default_role text NOT NULL, trust_directory_emails boolean NOT NULL, group_role_mappings_json jsonb NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE INDEX credbound_scim_configurations_workspace_idx ON credbound_scim_configurations(workspace_id);
CREATE TABLE credbound_scim_credentials (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), configuration_id uuid NOT NULL REFERENCES credbound_scim_configurations(id), prefix text NOT NULL UNIQUE, digest bytea NOT NULL, created_at timestamptz NOT NULL, expires_at timestamptz, last_used_at timestamptz, revoked_at timestamptz);
CREATE INDEX credbound_scim_credentials_configuration_idx ON credbound_scim_credentials(configuration_id);
CREATE TABLE credbound_scim_users (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), configuration_id uuid NOT NULL REFERENCES credbound_scim_configurations(id), user_id uuid NOT NULL REFERENCES credbound_users(id), external_id text, normalized_user_name text NOT NULL, display_name text NOT NULL, emails_json jsonb NOT NULL, profile_json jsonb NOT NULL, active boolean NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, deprovisioned_at timestamptz, UNIQUE (configuration_id, user_id), UNIQUE (configuration_id, normalized_user_name));
CREATE UNIQUE INDEX credbound_scim_users_external_id_idx ON credbound_scim_users(configuration_id, external_id) WHERE external_id IS NOT NULL;
CREATE INDEX credbound_scim_users_page_idx ON credbound_scim_users(configuration_id, created_at DESC, id DESC);
CREATE TABLE credbound_scim_groups (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), configuration_id uuid NOT NULL REFERENCES credbound_scim_configurations(id), external_id text, display_name text NOT NULL, member_ids_json jsonb NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, deleted_at timestamptz);
CREATE UNIQUE INDEX credbound_scim_groups_external_id_idx ON credbound_scim_groups(configuration_id, external_id) WHERE external_id IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX credbound_scim_groups_page_idx ON credbound_scim_groups(configuration_id, created_at DESC, id DESC);
CREATE TABLE credbound_oauth_issuers (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), issuer text NOT NULL UNIQUE, created_at timestamptz NOT NULL, data_json jsonb NOT NULL);
CREATE TABLE credbound_oauth_resources (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), issuer_id uuid NOT NULL REFERENCES credbound_oauth_issuers(id), workspace_id uuid NOT NULL REFERENCES credbound_workspaces(id), resource text NOT NULL UNIQUE, created_at timestamptz NOT NULL, data_json jsonb NOT NULL);
CREATE TABLE credbound_oauth_clients (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), issuer_id uuid NOT NULL REFERENCES credbound_oauth_issuers(id), client_id text NOT NULL, created_at timestamptz NOT NULL, data_json jsonb NOT NULL, UNIQUE (issuer_id, client_id));
CREATE TABLE credbound_oauth_initial_access_tokens (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), issuer_id uuid NOT NULL REFERENCES credbound_oauth_issuers(id), prefix text NOT NULL UNIQUE, registration_count integer NOT NULL, max_registrations integer NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, data_json jsonb NOT NULL);
CREATE TABLE credbound_oauth_grants (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), client_record_id uuid NOT NULL REFERENCES credbound_oauth_clients(id), resource_id uuid NOT NULL REFERENCES credbound_oauth_resources(id), user_id uuid NOT NULL REFERENCES credbound_users(id), workspace_id uuid NOT NULL REFERENCES credbound_workspaces(id), created_at timestamptz NOT NULL, data_json jsonb NOT NULL);
CREATE TABLE credbound_oauth_authorization_codes (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), prefix text NOT NULL UNIQUE, grant_id uuid NOT NULL REFERENCES credbound_oauth_grants(id), used_at timestamptz, expires_at timestamptz NOT NULL, data_json jsonb NOT NULL);
CREATE TABLE credbound_oauth_access_tokens (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), prefix text NOT NULL UNIQUE, grant_id uuid NOT NULL REFERENCES credbound_oauth_grants(id), data_json jsonb NOT NULL);
CREATE TABLE credbound_oauth_refresh_tokens (id uuid PRIMARY KEY CHECK (substring(id::text from 15 for 1) = '7' AND substring(id::text from 20 for 1) IN ('8', '9', 'a', 'b')), family_id uuid NOT NULL CHECK (substring(family_id::text from 15 for 1) = '7' AND substring(family_id::text from 20 for 1) IN ('8', '9', 'a', 'b')), prefix text NOT NULL UNIQUE, grant_id uuid NOT NULL REFERENCES credbound_oauth_grants(id), used_at timestamptz, revoked_at timestamptz, expires_at timestamptz NOT NULL, data_json jsonb NOT NULL);
CREATE INDEX credbound_oauth_refresh_family_idx ON credbound_oauth_refresh_tokens(family_id);
